mapper.select:
select id, voc_Id, topic_type, topic, vocabulary
from  review_topic

    topic_type=1 and is_deleted=0

       and vocabulary LIKE #{keyword}


limit #{limit} offset #{offset}

select count(*) from review_topic
topic_type=1 and is_deleted=0
and vocabulary LIKE #{keyword}

select rt.id, rt.voc_Id, rt.topic_type, rt.topic, rt.vocabulary
from review_topic rt
inner join voc_chap_book vcb on rt.voc_id=vcb.voc_id
where
    vcb.book_id = #{bookId}

        and vcb.chapter_id = #{chapterId}


        and ( rt.vocabulary LIKE #{keyword})

and rt.is_deleted = 0 and vcb.is_deleted = 0
limit #{limit} offset #{offset}

select count(*) from review_topic rt inner join voc_chap_book vcb on rt.voc_id=vcb.voc_id where vcb.book_id = #{bookId}
and vcb.chapter_id = #{chapterId}
and ( rt.vocabulary LIKE #{keyword})
and rt.is_deleted = 0 and vcb.is_deleted = 0

select tmp.tid
from (
select rst.tid
from review_sub_topic rst inner join voc_chap_book vcb on vcb.book_id = #{bookId} and rst.voc_id=vcb.voc_id and
rst.is_deleted=0


        and vcb.chapter_id = #{chapterId}


        and ( rst.vocabulary LIKE #{keyword})


group by rst.tid
) tmp limit #{limit} offset #{offset}

select count(*)
from (
    select rst.tid
    from review_sub_topic rst inner join voc_chap_book vcb on vcb.book_id = #{bookId} and rst.voc_id=vcb.voc_id and rst.is_deleted=0


        and vcb.chapter_id = #{chapterId}


        and ( rst.vocabulary LIKE #{keyword})


    group by rst.tid
) tmp

select tmp.tid
from (
select rst.tid
from review_sub_topic rst

    rst.is_deleted=0

        and ( rst.vocabulary LIKE #{keyword})


group by rst.tid
) tmp limit #{limit} offset #{offset}
